using AegisCore.Application.Platform;
using AegisCore.Domain;
using AegisCore.Domain.Entities;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace AegisCore.API.Controllers;

// OPTIONAL-26 Cafeteria Management
[ApiController][Route("api/cafeteria")] [Authorize] public class CafeteriaController : ControllerBase { private ICafeteriaService _s; public CafeteriaController(ICafeteriaService s) => _s = s; [HttpPost("units")] public async Task<IActionResult> CreateUnit([FromBody] CafeteriaUnit unit, CancellationToken ct) => Ok(await _s.CreateUnitAsync(unit, ct)); [HttpPost("menu-items")] public async Task<IActionResult> AddMenuItem([FromBody] MenuItem item, CancellationToken ct) => Ok(await _s.AddMenuItemAsync(item, ct)); [HttpPost("orders")] public async Task<IActionResult> PlaceOrder([FromQuery] Guid studentId, [FromQuery] Guid menuItemId, [FromQuery] Guid unitId, [FromQuery] int quantity, CancellationToken ct) => Ok(await _s.PlaceOrderAsync(studentId, menuItemId, unitId, quantity, ct)); [HttpPost("forecast")] public async Task<IActionResult> Forecast([FromQuery] Guid menuItemId, [FromQuery] Guid unitId, [FromQuery] DateTime date, CancellationToken ct) => Ok(await _s.GenerateForecastAsync(menuItemId, unitId, date, ct)); [HttpPost("vendors/{vendorId:guid}/evaluate")] public async Task<IActionResult> EvaluateVendor(Guid vendorId, [FromQuery] string month, CancellationToken ct) => Ok(await _s.EvaluateVendorAsync(vendorId, month, ct)); [HttpGet("units/{unitId:guid}/orders")] public async Task<IActionResult> PendingOrders(Guid unitId, CancellationToken ct) { var o = await _s.GetPendingOrdersAsync(unitId, ct); return Ok(new { total = o.Count, orders = o }); } [HttpGet("units/{unitId:guid}/alerts")] public async Task<IActionResult> InventoryAlerts(Guid unitId, CancellationToken ct) { var a = await _s.GetInventoryAlertsAsync(unitId, ct); return Ok(new { total = a.Count, alerts = a }); } }

// Personality Mode
[ApiController][Route("api/personality")] [Authorize] public class PersonalityController : ControllerBase { private IPersonalityModeService _s; public PersonalityController(IPersonalityModeService s) => _s = s; [HttpGet("config")] public async Task<IActionResult> GetConfig(CancellationToken ct) => Ok(await _s.GetConfigAsync(ct)); [HttpPut("config")] public async Task<IActionResult> UpdateConfig([FromQuery] bool isEnabled, [FromQuery] bool isLockedOff, CancellationToken ct) => Ok(await _s.UpdateConfigAsync(isEnabled, isLockedOff, ct)); [HttpPut("users/{userId:guid}/preference")] public async Task<IActionResult> SetPreference(Guid userId, [FromQuery] bool isActive, CancellationToken ct) { await _s.SetUserPreferenceAsync(userId, isActive, ct); return Ok(new { message = "Preference saved." }); } [HttpGet("users/{userId:guid}/active")] public async Task<IActionResult> IsActive(Guid userId, CancellationToken ct) => Ok(new { isActive = await _s.IsActiveForUserAsync(userId, ct) }); }

// Chart System
[ApiController][Route("api/charts")] [Authorize] public class ChartsController : ControllerBase { private IChartService _s; public ChartsController(IChartService s) => _s = s; [HttpPost] public async Task<IActionResult> Create([FromBody] ChartConfiguration config, CancellationToken ct) => Ok(await _s.CreateChartAsync(config, ct)); [HttpPost("{chartId:guid}/insight")] public async Task<IActionResult> ComputeInsight(Guid chartId, CancellationToken ct) => Ok(await _s.ComputeInsightAsync(chartId, ct)); [HttpGet("published")] public async Task<IActionResult> Published(CancellationToken ct) { var c = await _s.GetPublishedChartsAsync(ct); return Ok(new { total = c.Count, charts = c }); } }

// OCR Integration
[ApiController][Route("api/ocr")] [Authorize] public class OcrController : ControllerBase { private IOcrIntegrationService _s; public OcrController(IOcrIntegrationService s) => _s = s; [HttpPost("providers")] public async Task<IActionResult> RegisterProvider([FromBody] OcrProviderConfig config, CancellationToken ct) => Ok(await _s.RegisterProviderAsync(config, ct)); [RequestSizeLimit(5 * 1024 * 1024)][HttpPost("extract/{configId:guid}")] public async Task<IActionResult> Extract(Guid configId, [FromQuery] string documentType, CancellationToken ct) { using var ms = new MemoryStream(); await Request.Body.CopyToAsync(ms, ct); return Ok(new { text = await _s.ExtractTextAsync(configId, ms.ToArray(), documentType, ct) }); } [HttpGet("providers")] public async Task<IActionResult> GetProviders(CancellationToken ct) { var p = await _s.GetProvidersAsync(ct); return Ok(new { total = p.Count, providers = p }); } }

// Improved Plagiarism Detection Engine
[ApiController][Route("api/plagiarism-engine")] [Authorize] public class PlagiarismEngineController : ControllerBase { private IPlagiarismEngineService _s; public PlagiarismEngineController(IPlagiarismEngineService s) => _s = s; [HttpPost("similarity")] public async Task<IActionResult> Similarity([FromQuery] string textA, [FromQuery] string textB, CancellationToken ct) { var sim = await _s.ComputeCosineSimilarityAsync(textA, textB, ct); return Ok(new { similarity = sim }); } [HttpPost("collusion/{assignmentId:guid}")] public async Task<IActionResult> Collusion(Guid assignmentId, CancellationToken ct) { var rings = await _s.DetectCollusionRingsAsync(assignmentId, ct); return Ok(new { total = rings.Count, suspectIds = rings }); } [RequestSizeLimit(1 * 1024 * 1024)][HttpPost("ai-detect")] public async Task<IActionResult> AiDetect(CancellationToken ct) { using var reader = new StreamReader(Request.Body); var text = await reader.ReadToEndAsync(ct); return Ok(new { aiProbability = await _s.ComputeAiProbabilityAsync(text, ct) }); } [RequestSizeLimit(1 * 1024 * 1024)][HttpPost("style-consistency/{studentId:guid}")] public async Task<IActionResult> StyleConsistency(Guid studentId, CancellationToken ct) { using var reader = new StreamReader(Request.Body); var text = await reader.ReadToEndAsync(ct); return Ok(new { consistency = await _s.ComputeStyleConsistencyAsync(studentId, text, ct) }); } }

// Improved Proctoring Integration
[ApiController][Route("api/proctoring-integration")] [Authorize] public class ProctoringIntegrationController : ControllerBase { private IProctoringIntegrationService _s; public ProctoringIntegrationController(IProctoringIntegrationService s) => _s = s; [HttpPost("lockdown/{sessionId:guid}")] public async Task<IActionResult> ValidateLockdown(Guid sessionId, CancellationToken ct) => Ok(new { isValid = await _s.ValidateBrowserLockdownAsync(sessionId, ct) }); [RequestSizeLimit(5 * 1024 * 1024)][HttpPost("face-analyze")] public async Task<IActionResult> FaceAnalyze(CancellationToken ct) { using var ms = new MemoryStream(); await Request.Body.CopyToAsync(ms, ct); return Ok(new { faceId = await _s.AnalyzeFacialFeaturesAsync(ms.ToArray(), ct) }); } [RequestSizeLimit(5 * 1024 * 1024)][HttpPost("multi-face")] public async Task<IActionResult> MultiFace(CancellationToken ct) { using var ms = new MemoryStream(); await Request.Body.CopyToAsync(ms, ct); return Ok(new { hasMultiple = await _s.DetectMultipleFacesAsync(ms.ToArray(), ct) }); } [RequestSizeLimit(5 * 1024 * 1024)][HttpPost("gaze")] public async Task<IActionResult> Gaze(CancellationToken ct) { using var ms = new MemoryStream(); await Request.Body.CopyToAsync(ms, ct); return Ok(new { deviationDegrees = await _s.EstimateGazeDirectionAsync(ms.ToArray(), ct) }); } }

// Improved Fee Defaulter ML Engine
[ApiController][Route("api/defaulter-ml")] [Authorize] public class DefaulterMlController : ControllerBase { private IDefaulterMlEngineService _s; public DefaulterMlController(IDefaulterMlEngineService s) => _s = s; [HttpPost("train")] public async Task<IActionResult> Train(CancellationToken ct) => Ok(new { baseRate = await _s.TrainRiskModelAsync(ct) }); [HttpGet("predict/{studentId:guid}")] public async Task<IActionResult> Predict(Guid studentId, CancellationToken ct) => Ok(new { probability = await _s.PredictDefaultProbabilityAsync(studentId, ct), drivers = await _s.IdentifyRiskDriversAsync(studentId, ct) }); [HttpGet("evaluate")] public async Task<IActionResult> Evaluate(CancellationToken ct) => Ok(new { avgConfidence = await _s.EvaluateModelPerformanceAsync(ct) }); }
